#include "robotblocks_runtime.h"


static void proceso_1() {
    static struct : RbProcessState {
        int32_t rb_repeticiones1{};
    } s;
    PT_BEGIN(s);
    while (true) {
        for (s.rb_repeticiones1 = 3; s.rb_repeticiones1 > 0; --s.rb_repeticiones1) {
            digitalWrite(21, 0);
            PT_SLEEP(s, 200);
            digitalWrite(21, 1);
            PT_SLEEP(s, 200);
            PT_YIELD(s);
        }
        PT_SLEEP(s, 1000);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); pinMode(21, OUTPUT); }

void loop() { rb_error_repeat(); proceso_1(); }
